window.roroShowError=function(inputId,message="",show=!0){const wrapper=roroGetWrapper(inputId);if(!wrapper)return;const error=RoroDom.qs(wrapper,".roro-input-error-container"),errorMessage=error?RoroDom.qs(error,".roro-input-error-message"):null;!error||!errorMessage||(errorMessage.textContent=message,RoroDom.toggle(error,show),manageBorderError(RoroDom.qs(wrapper,".roro-border-error"),show))},window.manageBorderError=function(elt,show=null){if(!elt)return;const reveal=show===null?elt.dataset.show==="1"||elt.dataset.show==="true":!!show,errorClasses=elt.dataset.class||"";reveal?RoroDom.addClass(elt,errorClasses):(RoroDom.removeClass(elt,errorClasses),elt.classList.add("roro-border-error")),elt.dataset.show=reveal?"1":"0"},window.normalizeInputName=function(name){return name.split(".").reduce((acc,part,i)=>i===0?part:`${acc}[${part}]`,"")},window.roroGetWrapper=function(inputId){const input=document.getElementById(inputId);let wrapper=document.getElementById("roro-wrapper-"+inputId);return input&&input.classList.contains("roro-input-radio")&&(wrapper=input.closest(".roro-wrapper-radio-container")),wrapper};
